    private val characterById = characters.associateBy { it.id }
    private val characterByName = characters.filter { it.name != "Unknown" }.associateBy { it.name.lowercase().trim() }
    private val vehicleById = vehicles.associateBy { it.id }
    private val vehicleByName = vehicles.filter { it.name != "Unknown" }.associateBy { it.name.lowercase().trim() }

    fun findCharacter(id: Int): CharacterDef? = characterById[id]
    fun findCharacterByName(name: String): CharacterDef? = characterByName[name.lowercase().trim()]
    fun findVehicle(id: Int): VehicleDef? = vehicleById[id]
    fun findVehicleByName(name: String): VehicleDef? = vehicleByName[name.lowercase().trim()]
}
